import { createHash } from "node:crypto";

// Generated byte-for-byte from the Go-embedded historical ingest v1 schema.
// Tests fail if the packaged copy diverges from the canonical artifact.
const SCHEMA_BASE64 = "";
const SCHEMA_BYTES = Buffer.from(SCHEMA_BASE64, "base64");
const SCHEMA_DIGEST = createHash("sha256").update(SCHEMA_BYTES).digest("hex");

export function historicalIngestSchemaBytes() {
  return Buffer.from(SCHEMA_BYTES);
}

export function historicalIngestSchemaDigest() {
  return SCHEMA_DIGEST;
}

export function historicalIngestSchema() {
  return JSON.parse(SCHEMA_BYTES.toString("utf8"));
}
